-- 199_replace_decision_30_2024_local_voluntary_carbon_registries_accreditation_criteria_stored_in_english_only_as_non_official_translation_without_amendment.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (30) لسنة 2024 بتاريخ 2024/1/31 بشأن معايير اعتماد سجلات الكربون الطوعية المحلية لدى الهيئة
-- بالنص العربى المنشور بالوقائع المصرية - العدد 54 تابع (أ) فى 5 مارس سنة 2024 (الصفحات المطبوعة 3–13).
--
-- ===== الحالة السابقة (بذور 039 وما بعدها) =====
-- مخزَّن بصف واحد (article_no = 1، article_suffix_order = 0، 18694 حرفاً) كله بالإنجليزية، وعنوان القانون فى laws ورابط official_url (Done_Decree_No_30_2024.pdf) بالإنجليزية أيضاً،
-- فلا يجد البحث العربى ولا المساعد أى نص للقرار. وهو ترجمة إنجليزية غير رسمية تخالف النص الرسمى، ومن ذلك:
--   * المادة 1: تسمية البورصة "Egyptian Voluntary Carbon Market Exchange 'Africarbonex'" وعبارة "automatically recognized ... granted they complete standard KYC procedures" ولا مقابل لهما فى النص الرسمى
--     (الرسمى: "السوق الطوعية بالبورصات المصرية" و"تعتبر ... معتمدة لدى الهيئة دون الحاجة لاستيفاء الشروط الواردة بهذا القرار" بلا ذكر لإجراءات اعرف عميلك)؛
--   * المادة 2: تعريف "سجلات الكربون الطوعية" بصياغة مغايرة (verified carbon standards programs)، وتعريف "الجهات منشأة سجلات الكربون الطوعية" بتعريف مختلف المضمون (جهات لديها أنظمة إلكترونية لتسجيل الشهادات) بدل "الجهات المالكة والقائمة على حفظ وإدارة سجلات الكربون الطوعية"،
--     وتعريف الحياد الكربونى بعبارة "net zero emissions" بدل "الصافى الصفرى للانبعاثات الكربونية" مع جملة تعويض ناقصة؛
--   * ترويسة "Financial Regulatory Authority Board Decree No. 30/2024" وجملة "resolves the following on 31/1/2024" وتوقيع مطبوع "Dr. Mohammed Farid Saleh"، وصياغة حرة لباقى المواد لا نص رسمى.
-- (أُعيدت كتابة المتن كله من الأصل ولم يُعتمد على المخزَّن أساساً.)
--
-- ===== المصدر والمنهجية =====
-- الملف المرفوع (alamiria_2024_30.pdf) يضم ملف PDF من 11 صفحة (الوقائع المصرية العدد 54 تابع (أ)، الصفحات المطبوعة 3–13، بطبقة نصية بأشكال العرض العربية) ملحقاً به فى آخره صفحة HTML من بوابة التشريعات (تحميل مشوَّه)؛
-- فاقتُصر على جزء الـPDF بعد قطع الملحق بعد آخر %%EOF وإصلاح الملف، ولم يُستعمل شىء من الصفحة المرفقة. نُقل النص كاملاً من صور الصفحات بصرياً (200 dpi، ثلاثة أشرطة لكل صفحة)، ثم قوبل بالطبقة النصية (بعد توحيدها NFKC)
-- بمفاتيح الحروف المرتبة لكل كلمة (بالتمييز بين الهمزات والياء والألف المقصورة) وبمحاذاة تسلسلية وبكل الأرقام: لا فرق فى الديباجة والمواد إلا ما سببه انفصال التنوين فى الطبقة النصية (وفقاً، دولياً، ثانياً ...) وترويسة الصفحات وعناوين المواد
-- وعنوان القرار وسطر الجهة المصدرة وكلمة "قرر" والتوقيع، وسطر "ملخص عوائد المشروع (...)" فى المادة 5 الذى تتبعثر حروفه فى الطبقة النصية (حروفه موجودة كلها) فنُقل بصرياً.
-- أُبقى إملاء الأصل كما طُبع: "فى" و"هى" و"التى" بالألف المقصورة و"الصافى الصفري" بياء منقوطة و"المسؤولة" بالهمزة على الواو فى المادة 2 مقابل "المسئولين" بالهمزة على الياء فى المادة 3 و"InternationalCarbon" بلا مسافة (المادة 1) و"الالكترونى" بلا همزة (المادة 8)
-- و"سجل الكربون الطوعي" و"البيولوجي" و"ملغي" بياء منقوطة و"وإلى مراكز" و"أى" كما طُبعت، وعبارة "من إجمالى عمليات أعمال التحقق" (المادة 6 بند 1). التنوين على الأحرف نُقل بصرياً لأن الطبقة النصية تفقد بعضه (ثانياً/ثالثاً/رابعاً/خامساً/سادساً، سنوياً، مرفقاً ...).
-- حُذفت ترويسة الصفحات (الوقائع المصرية - العدد 54 تابع (أ) فى 5 مارس سنة 2024) وأرقامها وكلمة "قرارات" وسطر "الهيئة العامة للرقابة المالية" وعنوان القرار ورقمه وتاريخه (نُقلت إلى hierarchical_location للديباجة)
-- وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" وكلمة "قرر" وتوقيع رئيس مجلس الإدارة ("رئيس مجلس إدارة الهيئة العامة للرقابة المالية د/ محمد فريد صالح") المطبوع بآخر الصفحة 13. الأرقام لاتينية وعلامة النسبة (40٪) كُتبت (40%)
-- وأُسقطت علامات الضم والكسر والشدة (لا وجود لها فى المطبوع إلا ما يُحسب تنويناً) وأُبقى تنوين الفتح مكتوباً على الحرف قبل الألف كباقى الهجرات. الأقواس « » حول "نظام إصدار" وعلامات الاقتباس المزدوجة حول "لجنة حوكمة تكنولوجيا المعلومات" و"لجنة إدارة المخاطر التكنولوجية والأمن السيبرانى" و"وحدة" و"الشهادات" كما طُبعت.
--
-- ===== تعديلات التمثيل (معلنة) =====
--   * ألصقت علامات الترقيم بما قبلها ( ، ؛ . : ) حيث طُبعت بمسافة قبلها كما هى عادة الوقائع (مثل "ولائحته التنفيذية ؛" و"للهيئة ."). وكتابة أرقام القوانين فى الاطلاعات بلا أقواس كما طُبعت ("رقم 95 لسنة 1992").
--   * الألفاظ الإنجليزية داخل النص العربى (Standard Programs وUNFCCC وICROA وUser Interface وFirewall ...) بترتيب القراءة الطبيعى كما تقرأ على الصفحة لا بترتيب الطبقة النصية.
--   * ديباجة القرار صف مستقل (article_no = 0) من "بعد الاطلاع على قانون سوق رأس المال" إلى "... بتاريخ 2024/1/31؛" بست اطلاعات؛ وعنوان القرار وتاريخه فى hierarchical_location للصف.
--   * المواد 1–8 صفوف بعنوان "المادة الأولى - نطاق التطبيق" ... كما طُبع (المادة الثامنة بلا عنوان فرعى)؛ بنود المادتين 2 و3 وغيرهما "N- " كل بند فى سطر (بدل الترقيم المطبوع "١ –")، وعناوين أقسام المادة 3 (أولاً ... سادساً) والمادة 5 (أولاً، ثانياً) أسطر مستقلة
--     بالصيغة "أولاً - ...:"، وبنود (أ) (ب) (ج) ... فى سطور مستقلة كما طُبعت.
--
-- ===== الهيكل =====
-- 9 صفوف، 9 نسخ (version_no = 1): الديباجة (article_no = 0)، المواد 1–8 (article_suffix_order = 0). لا هوامش ولا تعديلات فى المصدر. المفتاح (1، 0) هو المفتاح المخزَّن نفسه فلا تعيد بذرة القرار
-- إدراج الصف القديم (إدراج laws فى البذور ON CONFLICT DO NOTHING وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود؛ وقد شُغِّلت كتلة البذرة محلياً فلم تُدرج شيئاً).
--
-- ===== التاريخ والنسخ =====
-- المادة 8: "ينشر هذا القرار فى الوقائع المصرية ... ويعمل به من اليوم التالى لتاريخ نشره بالوقائع المصرية"، والنشر فى العدد 54 تابع (أ) بتاريخ 5 مارس 2024، فـ effective_from = 2024-03-06 لكل الصفوف التسعة.
-- ولا amended_by: بُحث عن قرارات لاحقة تعدل هذا القرار فلم يوجد (لا نص "وفقاً لآخر تعديل" منشور له على صفحة الهيئة بخلاف القرار 31/2024، والقراران 36/2026 و115/2026 لا يذكرانه)؛ وهذا غياب دليل لا دليل غياب، ويُراجَع قانونياً.
-- لا نسخة للقرار قبل 2024-03-06 فى الاستعلام بالتاريخ (فجوة معلنة). لا تُمس بيانات laws (العنوان الإنجليزى والرابط الإنجليزى؛ enacted_at = 2024-01-31 صحيح بالفعل ولا يلزم تغييره)، وتُترك لهجرة بيانات laws المؤجلة (العنوان العربى والرابط).
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (9 صفوف بديباجة سليمة والمادة الثامنة موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف
-- (عدد، لفظ مغاير للأصل، أرقام أو نسب مغايرة، بقايا ترويسة أو تذييل أو توقيع أو وصلات مقلوبة، تاريخ سريان الصفوف، إجمالى الطول 14048 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix199$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[199] القرار 30/2024 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 9
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[199] القرار 30/2024 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[199] أُزيلت % مادة من القرار 30/2024 (صف واحد مخزن بالإنجليزية فقط (ترجمة غير رسمية للقرار) بنص مغاير للنص الرسمى)', v_n;
  END IF;
END
$fix199$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (30) لسنة 2024 بتاريخ 2024/1/31 بشأن معايير اعتماد سجلات الكربون الطوعية المحلية لدى الهيئة$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 ولائحته التنفيذية؛
وعلى القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى قرار مجلس إدارة الهيئة رقم 57 لسنة 2023 بشأن لجنة الإشراف والرقابة على وحدات خفض الانبعاثات الكربونية واختصاصاتها؛
وعلى قرار مجلس إدارة الهيئة رقم 163 لسنة 2023 بشأن معايير قيد جهات التحقق والمصادقة لمشروعات خفض الانبعاثات الكربونية لدى الهيئة؛
وبعد العرض على لجنة الإشراف والرقابة على وحدات خفض الانبعاثات الكربونية باجتماعها المنعقد بتاريخ 2024/1/29؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2024/1/31؛$b0_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى - نطاق التطبيق$t1_0$, $b1_0$تسرى أحكام هذا القرار فى شأن المعايير المتطلبة لاعتماد سجلات الكربون الطوعية المحلية لدى الهيئة بغرض تسجيل مشروعات خفض الانبعاثات الكربونية وإصدار شهادات خفض الانبعاثات الكربونية القابلة للتداول بالسوق الطوعية بالبورصات المصرية.
وتعتبر سجلات الكربون الطوعية الدولية المعترف بها من قبل InternationalCarbon Reduction and Offset Alliance (ICROA) معتمدة لدى الهيئة دون الحاجة لاستيفاء الشروط الواردة بهذا القرار.$b1_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية - تعريفات$t2_0$, $b2_0$يقصد فى تطبيق أحكام هذا القرار بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
1- شهادات خفض الانبعاثات الكربونية: هى أدوات مالية قابلة للتداول تمثل وحدات خفض انبعاثات غازات الاحتباس الحرارى، وتمثل كل "وحدة" طنًا من انبعاثات غاز ثانى أكسيد الكربون المكافئ، وتصدر لصالح مطور مشروع الخفض وذلك بعد الانتهاء من أعمال التحقق والمصادقة وفقًا لمعايير ومنهجيات خفض الانبعاثات الكربونية المعترف بها دوليًا، التى تقوم بها جهات التحقق والمصادقة سواء المحلية أو الدولية المقيدة بالقائمة المعدة لدى الهيئة لهذا الغرض، ويشار إليها فى أحكام هذا القرار ب "الشهادات".
2- مطورى المشروعات (Project Developers): هى الجهات المسؤولة عن تنفيذ مشروعات الخفض التى يتم بموجبها إصدار شهادات خفض الانبعاثات الكربونية بالسجلات بعد اعتماد جهات التحقق والمصادقة.
3- جهات وضع المعايير والمنهجيات (Standard Programs): هى الجهات التى تضع أسس ومنهجيات قياس خفض الانبعاثات الكربونية وفقًا لمنهجيات معترف بها دوليًا، ومنها منهجيات اتفاقية الأمم المتحدة الإطارية المعنية بتغير المناخ United Nations Framework Convention on Climate Change (UNFCCC) والمنهجيات المعتمدة من قبل International Carbon Reduction and Offset Alliance (ICROA)، أو وفقًا للمنهجيات المعتمدة محليًا من الجهات الحكومية المختصة فى هذا الشأن.
4- سجلات الكربون الطوعية (Carbon Credits Registries): هى أنظمة حفظ مركزية إلكترونية تتضمن سجلات لإصدار وتسجيل وتتبع تسلسل نقل ملكية شهادات خفض الانبعاثات الكربونية والناتجة عن تنفيذ مشروعات خفض الانبعاثات الكربونية وفقًا للمنهجيات الصادرة عن جهات وضع المعايير والمنهجيات (Standard Programs).
5- الجهات منشأة سجلات الكربون الطوعية: هى الجهات المالكة والقائمة على حفظ وإدارة سجلات الكربون الطوعية.
6- الحياد الكربونى: هو التوازن بين الانبعاثات الكربونية وإجراءات الحد من هذه الانبعاثات أو تعويضها، بهدف تخفيض الانبعاثات الكربونية إلى أقصى حد والتعويض عما لا يمكن التخلص منه للوصول إلى الصافى الصفري للانبعاثات الكربونية.$b2_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - متطلبات اعتماد سجلات الكربون الطوعية لدى الهيئة$t3_0$, $b3_0$يشترط لاعتماد سجلات الكربون الطوعية لدى الهيئة استيفاء المتطلبات الآتية:
أولًا - متطلبات عامة:
1- أن يتم تسجيل مشروعات خفض الانبعاثات الكربونية بالسجل وفقًا لقواعد وإجراءات محددة ومعتمدة من قبل الجهة منشأة السجل.
2- أن يتيح السجل تتبع تسلسل نقل ملكية شهادات خفض الانبعاثات الكربونية ابتداءً من الإصدار ثم نقل الملكية ثم الإلغاء لاستخدامها فى الغرض النهائى بهدف تحقيق الحياد الكربونى.
3- أن يكون لكل مشروع خفض رقم تعريفى موحد خاص به.
4- أن يكون لكل شهادة رقم تعريفى موحد خاص بها.
5- إتاحة ونشر جميع المعلومات الأساسية لمشروعات خفض الانبعاثات الكربونية، بما فى ذلك توصيف المشروعات وتقارير المتابعة والتقارير الصادرة عن جهات التحقق والمصادقة والبيانات القانونية.
6- أن تتضمن قواعد عمل السجل ما يفيد عدم جواز تسجيل مشروعات خفض الانبعاثات الكربونية المسجلة لديها بأى سجلات أخرى.
7- أن يبرم السجل عقد مع مطور المشروع يحدد حقوق والتزامات كل طرف.
8- أن يسمح السجل بالربط بينه وبين شركات التسوية والمقاصة المرخص لها من الهيئة وكذا تبادل البيانات إلكترونيًا وعلى وجه الأخص بيانات تسلسل نقل ملكية الشهادات.
9- أن يقدم السجل للهيئة الشروط والأحكام وشروط الاستخدام.
ثانيًا - متطلبات متعلقة بأعمال التحقق والمصادقة:
1- وجود مدير تنفيذى للإشراف على نشاط السجل، على أن يتم تعيينه بقرار من مجلس إدارة الجهة المنشأة للسجل ويجوز أن يكون من ضمن أعضاء مجلس إدارة الجهة.
2- أن يتوافر لدى السجل قائمة بأسماء جهات التحقق والمصادقة المعتمدة لديه وفقًا لمتطلبات ومعايير الاعتماد الصادرة عنه، وذلك بمراعاة أحكام قرار مجلس إدارة الهيئة رقم 163 لسنة 2023 المشار إليه.
3- أن يحدد السجل القطاعات التى يتم تسجيل مشروعات خفض الانبعاثات الكربونية بها.
4- أن يكون لدى السجل قواعد تكفل عدم تعارض المصالح بين الجهة منشأة السجل أو الجهات الممولة للمشروعات مع جهات التحقق والمصادقة.
ثالثًا - المتطلبات المتعلقة بالحوكمة:
يجب أن يتوفر بالجهة منشأة السجل متطلبات الحوكمة الآتية:
1- أن يكون لديها هيكل تنظيمى واضح يتناسب مع متطلبات حجم النشاط متضمنًا توافر عدد من العاملين والوصف الوظيفى لهم ومؤهلاتهم العلمية بالإضافة إلى الخبرات المهنية التى تتناسب مع المسئوليات والمهام الموكلة إليهم.
2- ألا يكون لأى من أعضاء مجلس الإدارة أو المسئولين عن الجهة أية مصلحة مباشرة أو غير مباشرة فى الأعمال والعقود التى تتم لصالح السجل بالمجالات المرتبطة بنشاط إمساك سجلات الكربون الطوعية.
3- الحصول على موافقة مسبقة من الجمعية العامة أو ما يقوم مقامها فى الأشخاص الاعتبارية الأخرى فى حالة العقود التى يوجد فيها مصلحة شخصية لأحد أعضاء مجلس الإدارة أو المسئولين عن الجهة، مع إثبات ذلك بمحضر اجتماع السلطة المختصة، كما لا يجوز اشتراك أى من الفئات المشار إليها بهذا البند فى القرار الصادر فى هذا الشأن.
4- وجود لجنة أو أكثر منبثقة من مجلس الإدارة تسمى "لجنة حوكمة تكنولوجيا المعلومات" تكون مسئولة عن الإشراف على تنفيذ إطار عمل حوكمة تكنولوجيا المعلومات والتأكد من ملائمة دورة العمل والمسئولين عن تنفيذها وتقديم الملاحظات والتوصيات واقتراح ما تراه من تعديلات لضمان فعالية سير العمل، وكذا لجنة أو أكثر منبثقة من مجلس الإدارة تسمى "لجنة إدارة المخاطر التكنولوجية والأمن السيبراني" تكون مسئولة عن الإشراف على تنفيذ إطار عمل إدارة المخاطر التكنولوجية والأمن السيبرانى والتأكد من ملائمة دورة العمل والمسئولين عن تنفيذها وتقديم الملاحظات والتوصيات واقتراح ما تراه من تعديلات لضمان فعالية سير العمل.
5- التعهد بالتزام أعضاء مجلس الإدارة ببذل العناية الكافية للقيام بأعمال نشاط إمساك سجلات الكربون الطوعية.
رابعًا - المتطلبات المتعلقة بأنظمة المعلومات (التطبيقات وقواعد البيانات):
1- توافر «نظام إصدار» منفصل لتنظيم أعمال التحقق والمصادقة والفحص الميدانى، على أن يكون هذا النظام داعمًا للدورة المستندية بين جهة التسجيل (سجل الكربون الطوعي) وجهة الإصدار (مطور المشروع) والجهات المهنية ذات الاختصاص المصدرة لها (جهات التحقق والمصادقة) والتى تكون مسئولة عن صحة الإصدار، مع تحديد اختصاصات / صلاحيات كل مستخدم.
2- توافر (نظام سجلات) لإدارة تسلسل ملكية شهادات خفض الانبعاثات الكربونية على أن يكون هذا النظام داعمًا لعمليات التسجيل والتعديل والإلغاء لشهادات خفض الانبعاثات الكربونية، وكذلك يتيح الاطلاع على البيانات ذات الأثر، كما يتيح الربط مع أنظمة أخرى من خلال واجهة برمجة التطبيقات وفقا للشروط والمواصفات التى تحددها الجهات المسئولة عنها ومنها نظام شركات التسوية والمقاصة ونظام التداول، مع تحديد اختصاصات و/أو صلاحيات كل مستخدم وضمان أن يتوافر نظام لتخزين واسترجاع المعاملات وبيانات وسجلات النشاط لمدة لا تقل عن خمس سنوات.
3- يشترط لتعديل أى من البرامج أو الأنظمة الحصول على موافقة مسبقة من الهيئة.
4- أن يكون لدى النظام واجهة مستخدم (User Interface) واضحة وسهلة الاستخدام تتيح سهولة التنقل ووصول المعلومات لمختلف المستخدمين، بما فى ذلك مطورو المشروعات وجهات التحقق والمصادقة والمتعاملين والجمهور.
5- أن يكون لدى النظام تطبيق يمكن الوصول إليه من خلال مختلف الأجهزة الإلكترونية متعددة الاستخدام وكذا أنظمة دعم التشغيل الرئيسية مع دعم التطبيق لعدد من اللغات، أو تقديم خطة تتضمن التوقيتات الزمنية لتمكين السجل من تفعيل التطبيق على مختلف الأجهزة الإلكترونية.
6- أن يكون لدى النظام آليات آمنة لتشفير عمليات تسجيل الدخول وعمليات التدقيق الأمنى المنتظمة، وحماية البيانات الحساسة وخصوصية المستخدم.
7- أن يكون لدى النظام نموذج بيانات واضح يحدد تصنيف البيانات ومحدداتها وتوثيقها وتعزيز قابلية التشغيل المتبادل.
8- أن يكون لدى النظام قاعدة بيانات تتوافق مع مختلف النظم والمنصات ذات الصلة، مع إتاحة تبادل للبيانات وتكاملها بسلاسة عند الضرورة.
9- أن يكون لدى النظام قاعدة بيانات آمنة وقابلة للتطوير وقادرة على التعامل مع البيانات بدرجة عالية من الكفاءة والسلامة.
10- أن يقوم النظام بإعداد نسخ احتياطية من البيانات مع وجود هيكل واضح يسهل عملية استرجاعها وتحديثها وإدارتها بصورة فعالة تضمن الاستمرارية فى حالة فشل النظام.
11- أن يكون لدى النظام إجراءات تدقيق ومراجعة حسابات شاملة وواضحة لرصد أى محاولة للتلاعب بجميع معاملات السجل بما يضمن الشفافية وإمكانية التتبع.
12- أن يكون لدى النظام إجراءات لضمان الرقابة والامتثال للمعايير واللوائح والمنهجيات ذات الصلة المطبقة بأسواق الكربون الطوعية.
13- أن يكون لدى النظام آليات توفر أدوات الإفصاح وإعداد التقارير اللازمة المختلفة لكافة الأطراف ذات الصلة.
14- أن يكون لدى النظام آليات تسمح بالتعامل بكفاءة مع النسب المتزايدة من البيانات والمستخدمين.
15- أن يقوم النظام بالرصد المستمر للأداء، وإجراء التحديثات اللازمة بصورة منتظمة.
16- أن يقوم النظام بإتاحة مواد تدريبية شاملة، بما فى ذلك الأدلة والأسئلة الشائعة ومقاطع الفيديو التعليمية، لتوجيه المستخدمين فى استخدام السجل بالإضافة إلى تقديم الدعم الفنى للمستخدمين.
17- أن يقوم النظام بإتاحة آليات تتيح دمج تعليقات المستخدمين من أجل تحسين أداء النظام.
خامسًا - متطلبات البنية التكنولوجية:
1- أن يوفر السجل حاسبات ووسائل التخزين ذات قدرات وسعات مناسبة لمتطلبات الأنظمة (التطبيقات وقواعد البيانات) وتبادل المعلومات باستخدام نظم تشغيل وبرمجيات مرخصة وبتصميم يوفر العمل الدائم بدون توقف.
2- أن يوفر السجل شبكات ووسائل اتصال (خطوط ربط) ذات قدرات وسعات مناسبة لمتطلبات الحاسبات ووسائل التخزين باستخدام بروتوكولات أمان قوية وبتصميم يوفر العمل الدائم بدون توقف.
3- أن يوفر السجل وسائل الحماية وتأمين المعلومات – Protection & Security Mechanisms ومنها:
(أ) نظام الجدار النارى – Firewall.
(ب) نظام منع الاختراق – Intrusion Prevention.
(ج) الحماية للأجهزة الطرفية – End Point Protection.
(د) التحديث الدورى لنظم التشغيل والبرمجيات.
(ه) التحكم فى الدخول وإدارة الصلاحيات، باستخدام تقنيات التحقق متعدد العوامل، وحسن إدارة كلمة المرور وإلزام تحديثها، ومنع دخول نفس المستخدم من أكثر من جهاز وعدم السماح بإبقاء الاتصال غير الفاعل.
(و) الفصل المادى بين الأنظمة المختلفة حال استخدام بيئة افتراضية.
(ز) تشفير البيانات المتداولة باستخدام تقنيات وشهادات التشفير المناسبة.
4- يلتزم السجل بعمل اختبارات الاختراقات الأمنية (Penetration Test) لقياس مدى تأمين الشبكات والبيانات مرة سنويًا على الأقل وتسليم نسخة من هذه الاختبارات للهيئة.
5- يجب إبلاغ الهيئة لحظة حدوث اختراقات أمنية (Security Incident) تحدث على مستوى البنية التكنولوجية للمعلومات والأنظمة العاملة عليها.
6- أن يقوم السجل بتوفير آليات ضبط التوقيت (Time Synchronization) لجميع الأنظمة والأجهزة المثبتة على هذه الأنظمة على توقيت واحد يكون مماثلًا لتوقيت أنظمة شركات التسوية والمقاصة وأنظمة التداول.
7- أن يقوم السجل بتوفير آليات تسجيل جميع الأحداث (Logging Events) التى تحدث على جميع الأنظمة والأجهزة والاحتفاظ بسجلات الأحداث لمدة لا تقل عن خمس سنوات، من خلال رقم لا يتكرر لكل حدث ولكل نظام مقرون بتوقيت الحدث.
سادسًا - متطلبات البنية التحتية للتجهيزات:
1- أن يوفر السجل بنية تحتية للتجهيزات فى مقر رئيسى وأخرى فى مقر احتياطى للطوارئ (Disaster Recovery Environment) بنفس المواصفات والقدرات وذات سعة مناسبة لمتطلبات البنية التكنولوجية وما تحتاجه من:
(أ) مصادر الطاقة.
(ب) أنظمة التحكم فى درجة الحرارة والرطوبة.
(ج) أنظمة الإنذار والمكافحة للحريق.
(د) أنظمة المراقبة بالكاميرات.
(ه) أنظمة التحكم المادى بالدخول والخروج للأفراد والأجهزة، وبتصميم يوفر العمل الدائم بدون توقف.
2- أن يوفر السجل آليات التأمين المادى والتحكم فى الدخول والخروج من وإلى مراكز البيانات، مع الاحتفاظ بسجلات الدخول والخروج لمدة لا تقل عن ثلاثة أشهر للمراجعة عند الحاجة.
3- أن يوفر السجل ضوابط بيئية داخل مراكز البيانات لضمان أداء مثالى للأجهزة والأنظمة المختلفة.
4- أن يوفر السجل آليات أنظمة احتياطية وموثوقة لتوفير الطاقة.
5- أن يوفر السجل آليات فعالة فى استخدام الطاقة لتقليل البصمة الكربونية إلى أدنى حد ممكن.$b3_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة - تقديم طلب الاعتماد لدى الهيئة$t4_0$, $b4_0$على السجلات الراغبة فى الاعتماد لدى الهيئة استيفاء نموذج طلب الاعتماد المعد من الهيئة لإمساك سجلات الكربون الطوعية، مرفقًا به المستندات الدالة على استيفاء الشروط المتطلبة للاعتماد على النحو المشار إليه بهذا القرار، وأى مستندات أخرى ترى الهيئة ضرورة تقديمها.
وتبت الهيئة فى طلب القيد خلال ثلاثين يومًا من تاريخ تقديمه مستوفيًا المستندات المؤيدة له.$b4_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة - الحد الأدنى من المعلومات الواجب توافرها فى سجلات الكربون الطوعية$t5_0$, $b5_0$تلتزم سجلات الكربون الطوعية المعتمدة لدى الهيئة بالاحتفاظ بالحد الأدنى من المعلومات على النحو الآتى:
أولًا - معلومات عن وصف المشروع:
1- اسم المشروع والكود التعريفى الموحد الخاص به.
2- الموقع الجغرافى للمشروع والإحداثيات الخاصة به.
3- اسم مطور المشروع.
4- اسم جهة التحقق والمصادقة.
5- مدة المشروع.
6- ملخص عوائد المشروع (العامة والمناخية والمجتمعية والخاصة بالتنوع البيولوجي).
7- عدد شهادات خفض الانبعاثات الكربونية التى تصدر سنويًا وتاريخ الإصدار.
8- حالة المشروع (مسجل أو مصادق عليه أو تم التحقق منه أو مكتمل أو مرفوض أو ملغي).
ثانيًا - معلومات عن شهادات خفض الانبعاثات الكربونية:
1- عدد الشهادات المصدرة وتاريخ إصدارها.
2- تسلسل ملكية الشهادات بالسجل.
3- الرصيد الحالى لعدد الشهادات القائمة وتاريخها.
4- عدد الشهادات التى تم إعدامها.
5- البيانات الرئيسية عن مالك الشهادة وعلى وجه الأخص اسمه وجنسيته.
6- حالة الشهادة (مصدرة أو معدومة أو منتهية الصلاحية).$b5_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, $t6_0$المادة السادسة - متطلبات الفحص الميدانى$t6_0$, $b6_0$تلتزم سجلات الكربون الطوعية المعتمدة لدى الهيئة بما يلى:
1- القيام بفحص ما لا يقل عن (40%) من إجمالى عمليات أعمال التحقق والمصادقة لمشروعات خفض الانبعاثات الكربونية المسجلة لديه بصورة سنوية ويجوز تخفيض هذه النسبة بناء على مبررات يقدمها السجل وتقبلها الهيئة على ألا تقل النسبة عن (20%) بأى حال من الأحوال.
2- أن تكون عينة الفحص معبرة إحصائيًا لأغلب المشروعات التى يفحصها السجل من حيث (الموقع الجغرافى وجهات التحقق والمصادقة وأحجام وأنواع المشروعات) مع الأخذ فى الاعتبار المشروعات مرتفعة المخاطر.
3- ألا تقل نسبة المشروعات التى يتم فحصها مكتبيًا بصورة سنوية عن (30%) من إجمالى عدد المشروعات المسجلة بالسجل.
4- حضور ممثلين عن السجل مع الفريق المختص بأعمال التحقق والمصادقة عند إجراء الزيارة الميدانية لتفقد مواقع مشروعات خفض الانبعاثات الكربونية.
5- مراجعة تقارير التحقق والمصادقة التفصيلية والقيام بتوثيق النتائج التى يتم التوصل إليها أثناء عملية الفحص الميدانى.$b6_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, $t7_0$المادة السابعة - التدابير$t7_0$, $b7_0$لمجلس إدارة الهيئة حال ثبوت مخالفة أى من الأحكام الواردة فى هذا القرار أو المعايير التى تصدرها الهيئة فى هذا الشأن، اتخاذ تدبير أو أكثر من التدابير الآتية:
1- توجيه التنبيه بالمخالفات المنسوبة وتحديد الفترة الزمنية اللازمة لإزالة أسبابها.
2- الإيقاف المؤقت لاعتماد السجل لدى الهيئة لمدة لا تجاوز ستة أشهر.
3- شطب السجل مع عدم جواز اعتماده لدى مرة أخرى إلا بعد مضى مدة لا تقل عن ستة أشهر.
4- شطب السجل مع عدم جواز اعتماده لدى الهيئة مرة أخرى.$b7_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
