  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-06', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t8_0$المادة الثامنة$t8_0$, $b8_0$ينشر هذا القرار فى الوقائع المصرية، وعلى الموقع الالكترونى للهيئة، ويعمل به من اليوم التالى لتاريخ نشره بالوقائع المصرية.$b8_0$
  FROM laws WHERE law_no = 30 AND law_year = 2024 AND kind = 'board_decision'
